var FEEDS = [
  {n:'CTA.A',    r:212400, v:0},
  {n:'UTP.SIP',  r:186900, v:0},
  {n:'OPRA.B12', r:1418000, v:0},
  {n:'MDP3.ES',  r:94600,  v:0},
  {n:'XDP.ARCA', r:71300,  v:0},
  {n:'PITCH.BZX',r:63800,  v:0},
  {n:'ITCH.TV',  r:128500, v:0},
  {n:'MITCH.LSE',r:22100,  v:0}
];
var SPK = ['▁','▂','▃','▄','▅','▆','▇'];
var rowsEl = root.querySelector('.fh-rows');
var totEl = root.querySelector('.fh-tot');
var gapsEl = root.querySelector('.fh-gaps');
var logEl = root.querySelector('.fh-log');
var clkEl = root.querySelector('.fh-clk');
var st = FEEDS.map(function(f){
  return {base:f.r, cur:f.r, age:20 + Math.random()*40, gaps:0, hist:[f.r,f.r,f.r,f.r,f.r], down:0, flash:0};
});
st[7].down = 5; st[7].age = 2400;
var els = FEEDS.map(function(f){
  var d = document.createElement('div');
  d.className = 'fh-row';
  d.innerHTML = '<span class="fh-nm"></span><span class="fh-spk"></span><span class="fh-msg"></span><span class="fh-age"></span><span class="fh-gap"></span><span class="fh-st"></span>';
  d.children[0].textContent = f.n;
  rowsEl.appendChild(d);
  return d;
});
function rate(v){ return v >= 1e6 ? (v/1e6).toFixed(2) + 'M' : v >= 100 ? (v/1e3).toFixed(1) + 'k' : Math.round(v) + ''; }
function ageTxt(ms){ return ms < 1000 ? Math.round(ms) + 'ms' : (ms/1000).toFixed(1) + 's'; }
function pad(n){ return (n < 10 ? '0' : '') + n; }
function stamp(){ var d = new Date(); return pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds()); }
function spark(h){
  var mx = Math.max.apply(null, h), mn = Math.min.apply(null, h), s = '';
  for (var i = 0; i < h.length; i++){
    var t = mx === mn ? 3 : Math.round((h[i] - mn) / (mx - mn) * 6);
    s += SPK[t];
  }
  return s;
}
function log(t){ logEl.textContent = stamp() + '  ' + t; }
var TICK = 420;
function paint(){
  if (!root.isConnected) return;
  var total = 0, gaps = 0;
  for (var i = 0; i < st.length; i++){
    var s = st[i], e = els[i];
    if (s.down > 0){
      s.down--;
      s.age += TICK;
      s.cur = Math.max(0, s.cur * 0.55);
      if (s.down === 0){
        s.gaps++;
        s.age = 30;
        s.cur = s.base;
        log(FEEDS[i].n + '  recovered from B-side · seq gap ' + (180 + ((Math.random()*900)|0)) + ' msgs');
      }
    } else {
      s.cur = Math.max(s.base * 0.72, s.base * (0.94 + Math.random() * 0.12));
      s.age = 6 + Math.random() * 70;
      if (Math.random() < 0.004){
        s.down = 4 + ((Math.random() * 8) | 0);
        log(FEEDS[i].n + '  stalled · no message for ' + (TICK/1000).toFixed(1) + 's · arbitrating');
      } else if (Math.random() < 0.006){
        s.gaps++;
        s.flash = 6;
        log(FEEDS[i].n + '  seq gap ' + (2 + ((Math.random()*40)|0)) + ' msgs · recovered A/B');
      }
    }
    s.hist.push(s.cur); if (s.hist.length > 5) s.hist.shift();
    total += s.cur; gaps += s.gaps;
    var cls = s.age < 250 ? 'fh-ok' : s.age < 1500 ? 'fh-warn' : 'fh-bad';
    var lab = s.age < 250 ? '● LIVE' : s.age < 1500 ? '◐ SLOW' : '○ STALE';
    e.children[1].textContent = spark(s.hist);
    e.children[2].textContent = rate(s.cur);
    e.children[2].className = 'fh-msg ' + cls;
    e.children[3].textContent = ageTxt(s.age);
    e.children[3].className = 'fh-age ' + (s.age < 250 ? '' : cls);
    e.children[4].textContent = s.gaps;
    e.children[4].className = 'fh-gap' + (s.flash > 0 ? ' fh-hit' : '');
    if (s.flash > 0) s.flash--;
    e.children[5].textContent = lab;
    e.children[5].className = 'fh-st ' + cls;
    e.className = 'fh-row' + (s.age >= 1500 ? ' fh-dead' : '');
  }
  totEl.textContent = rate(total);
  gapsEl.textContent = gaps;
  clkEl.textContent = stamp();
}
paint();
var iv = setInterval(paint, TICK);

