var B = [
  {lo:0,   hi:40,  lb:'<40',      w:1.2},
  {lo:40,  hi:60,  lb:'40-60',    w:14},
  {lo:60,  hi:80,  lb:'60-80',    w:31},
  {lo:80,  hi:100, lb:'80-100',   w:27},
  {lo:100, hi:140, lb:'100-140',  w:17},
  {lo:140, hi:200, lb:'140-200',  w:6.6},
  {lo:200, hi:300, lb:'200-300',  w:2.4},
  {lo:300, hi:500, lb:'300-500',  w:0.65},
  {lo:500, hi:900, lb:'>500',     w:0.15}
];
var W = 17, SLA = 300;
var rowsEl = root.querySelector('.lh-rows');
var els = B.map(function(b){
  var d = document.createElement('div');
  d.className = 'lh-row';
  d.innerHTML = '<span class="lh-lb"></span><span class="lh-bar"><span class="lh-on"></span><span class="lh-off"></span></span><span class="lh-pc"></span><span class="lh-ct"></span>';
  d.children[0].textContent = b.lb;
  rowsEl.appendChild(d);
  return d;
});
var nEl = root.querySelector('.lh-n'), p50El = root.querySelector('.lh-p50');
var p99El = root.querySelector('.lh-p99'), mxEl = root.querySelector('.lh-max');
var vEl = root.querySelector('.lh-verd'), ovEl = root.querySelector('.lh-ov');
function rep(c, n){ return n > 0 ? new Array(n + 1).join(c) : ''; }
function grp(n){ return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function pct(counts, n, q){
  var target = q * n, cum = 0;
  for (var i = 0; i < counts.length; i++){
    if (cum + counts[i] >= target){
      var f = counts[i] ? (target - cum) / counts[i] : 0;
      return B[i].lo + f * (B[i].hi - B[i].lo);
    }
    cum += counts[i];
  }
  return B[B.length - 1].hi;
}
function above(counts, n, x){
  var cum = 0, out = 0;
  for (var i = 0; i < counts.length; i++){
    if (B[i].lo >= x) out += counts[i];
    else if (B[i].hi > x) out += counts[i] * (B[i].hi - x) / (B[i].hi - B[i].lo);
    cum += counts[i];
  }
  return out / n * 100;
}
function draw(){
  if (!root.isConnected) return;
  var counts = [], n = 0, base = 88000 + Math.random() * 9000, skew = 0.85 + Math.random() * 0.45;
  for (var i = 0; i < B.length; i++){
    var w = B[i].w * (0.88 + Math.random() * 0.24) * (i >= 6 ? skew : 1);
    var c = Math.max(0, Math.round(base * w / 100));
    counts.push(c); n += c;
  }
  var mx = Math.max.apply(null, counts);
  var p50 = pct(counts, n, 0.5), p99 = pct(counts, n, 0.99);
  var worst = counts[8] > 0 ? 520 + Math.round(Math.random() * 380) : 300 + Math.round(Math.random() * 190);
  for (var j = 0; j < B.length; j++){
    var e = els[j], on = Math.round(counts[j] / mx * W);
    e.children[1].children[0].textContent = rep('█', on);
    e.children[1].children[1].textContent = rep('█', W - on);
    e.children[2].textContent = (counts[j] / n * 100).toFixed(1);
    e.children[3].textContent = grp(counts[j]);
    var mark = (p99 >= B[j].lo && p99 < B[j].hi) ? ' lh-mark' : '';
    e.className = 'lh-row' + (B[j].lo >= SLA ? ' lh-out' : B[j].lo >= 140 ? ' lh-tail' : '') + mark;
  }
  nEl.textContent = grp(n);
  p50El.textContent = Math.round(p50);
  p99El.textContent = Math.round(p99);
  mxEl.textContent = worst;
  var ok = p99 <= SLA;
  vEl.textContent = ok ? 'PASS' : 'BREACH';
  vEl.className = ok ? 'lh-pass' : 'lh-fail';
  ovEl.textContent = above(counts, n, SLA).toFixed(2) + '%';
}
draw();
var iv = setInterval(draw, 2200);

