var V = [
  ['XNYS', ['up','CTA/UTP','SIP-A-01',86,'04:12:38'], ['up','FIX 4.2','NYSE-OE-01',412,'04:12:40'], ['up','FIX 4.4','DROP-01',540,'04:12:41']],
  ['XNAS', ['up','ITCH 5.0','TV-01',74,'04:11:02'],  ['up','OUCH 4.2','NQ-OE-03',288,'04:11:05'], ['up','FIX 4.4','DROP-02',505,'04:11:06']],
  ['ARCX', ['up','XDP 2.1','ARC-MD-02',91,'04:12:38'],['deg','FIX 4.2','ARC-OE-01',1840,'00:06:12'],['up','FIX 4.4','DROP-03',560,'04:12:44']],
  ['BATS', ['up','PITCH 2.4','BZX-MD-01',68,'04:09:55'],['up','BOE 2.9','BZX-OE-02',241,'04:09:58'],['up','FIX 4.2','DROP-04',498,'04:09:59']],
  ['IEXG', ['up','DEEP 1.6','IEX-MD-01',122,'04:10:31'],['up','FIX 4.2','IEX-OE-01',388,'04:10:33'],['dn','FIX 4.2','DROP-05',0,'00:18:07']],
  ['XLON', ['deg','MITCH 5.2','LSE-MD-01',2410,'00:02:44'],['up','NTP 3.0','LSE-OE-01',1120,'07:31:20'],['up','FIX 5.0','DROP-06',1260,'07:31:22']],
  ['XETR', ['up','ETI 12.0','ETR-MD-01',980,'07:02:14'],['up','ETI 12.0','ETR-OE-01',1040,'07:02:16'],['up','FIX 4.4','DROP-07',1180,'07:02:17']],
  ['GLBX', ['up','MDP 3.0','CME-MD-01',148,'12:41:09'],['up','iLink 3','CME-OE-01',318,'12:41:11'],['na','--','--',0,'--']]
];
var LAB = {up:'● UP', deg:'◐ DEG', dn:'○ DOWN', na:'– N/A'};
var CLS = {up:'cm-up', deg:'cm-deg', dn:'cm-dn', na:'cm-na'};
var COL = ['MD','ORD','DROP'];
var grid = root.querySelector('.cm-grid');
var d1 = root.querySelector('.cm-d1'), d2 = root.querySelector('.cm-d2');
var sum = root.querySelector('.cm-sum');
var cells = [], tally = {up:0, deg:0, dn:0, na:0};
for (var r = 0; r < V.length; r++){
  var lab = document.createElement('div');
  lab.className = 'cm-v'; lab.textContent = V[r][0];
  grid.appendChild(lab);
  for (var c = 1; c <= 3; c++){
    var s = V[r][c][0];
    tally[s]++;
    var el = document.createElement('div');
    el.className = 'cm-c ' + CLS[s];
    el.textContent = LAB[s];
    el.tabIndex = 0;
    el.setAttribute('data-r', r); el.setAttribute('data-c', c - 1);
    grid.appendChild(el);
    cells.push(el);
  }
}
sum.textContent = tally.up + ' up · ' + tally.deg + ' deg · ' + tally.dn + ' down · ' + tally.na + ' n/a';
var sel = 1, hold = 0;
function grp(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function show(){
  var r = (sel / 3) | 0, c = sel % 3, d = V[r][c + 1];
  d1.textContent = V[r][0] + '/' + COL[c] + '  ' + d[1] + '  ' + d[2];
  if (hold > 0) return;
  if (d[0] === 'na'){
    d2.textContent = 'not provisioned · drop copy via clearing file';
  } else if (d[0] === 'dn'){
    d2.textContent = 'DOWN ' + d[4] + ' · tcp reset · retry 4/8 · seq held 12,884';
  } else {
    var rtt = d[3] + Math.round((Math.random() - 0.5) * (d[0] === 'deg' ? 420 : 24));
    d2.textContent = 'rtt ' + grp(Math.max(1, rtt)) + 'µs · hb 30s · seq ' + grp(8421000 + sel * 1373) + ' · up ' + d[4];
  }
}
function pick(i, focus){
  sel = (i + cells.length) % cells.length;
  for (var k = 0; k < cells.length; k++) cells[k].classList.toggle('cm-sel', k === sel);
  hold = 0;
  show();
  if (focus) cells[sel].focus();
}
grid.addEventListener('click', function(e){
  var t = e.target.closest ? e.target.closest('.cm-c') : null;
  if (t) pick(cells.indexOf(t), true);
});
grid.addEventListener('keydown', function(e){
  var k = e.key;
  if (k === 'ArrowRight') { pick(sel + 1, true); e.preventDefault(); }
  else if (k === 'ArrowLeft') { pick(sel - 1, true); e.preventDefault(); }
  else if (k === 'ArrowDown') { pick(sel + 3, true); e.preventDefault(); }
  else if (k === 'ArrowUp') { pick(sel - 3, true); e.preventDefault(); }
  else if (k === 'Enter') {
    var r = (sel / 3) | 0, c = sel % 3, st = V[r][c + 1][0];
    d2.innerHTML = st === 'up' || st === 'deg'
      ? '<span class="cm-ping">TestRequest sent · Heartbeat ack ' + (0.8 + Math.random() * 1.6).toFixed(1) + 'ms</span>'
      : 'TestRequest refused · session not established';
    hold = 8;
    e.preventDefault();
  }
});
grid.addEventListener('focusin', function(e){
  var t = e.target.closest ? e.target.closest('.cm-c') : null;
  if (t) pick(cells.indexOf(t), false);
});
pick(1, false);
var iv = setInterval(function(){
  if (!root.isConnected) return;
  if (hold > 0) { hold--; if (hold === 0) show(); return; }
  show();
}, 900);

