js:
var N = 34, TICK = 620;
var strip = root.querySelector('.hb-strip'), logEl = root.querySelector('.hb-log');
var lastEl = root.querySelector('.hb-last'), inEl = root.querySelector('.hb-in'), outEl = root.querySelector('.hb-out');
var trEl = root.querySelector('.hb-tr'), rrEl = root.querySelector('.hb-rr'), gpEl = root.querySelector('.hb-gp');
var stEl = root.querySelector('.hb-state');
var bars = [];
for (var i = 0; i < N; i++){
  var b = document.createElement('span');
  b.className = 'hb-b';
  strip.appendChild(b); bars.push(b);
}
var seqIn = 8421993, seqOut = 214882, testReq = 0, resend = 0, gaps = 0, miss = 0, mode = 'sync', recov = 0;
function grp(n){ return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function pad(n, w){ var s = String(n); while (s.length < w) s = '0' + s; return s; }
function stamp(){
  var d = new Date();
  return pad(d.getHours(),2) + ':' + pad(d.getMinutes(),2) + ':' + pad(d.getSeconds(),2) + '.' + pad(d.getMilliseconds(),3);
}
function log(kind, msg){
  var ln = document.createElement('div');
  ln.className = 'hb-ln';
  var a = document.createElement('span'); a.className = 'hb-ts'; a.textContent = stamp();
  var b = document.createElement('span'); b.className = 'hb-k hb-k-' + kind.toLowerCase(); b.textContent = kind;
  var c = document.createElement('span'); c.className = 'hb-m'; c.textContent = msg;
  ln.appendChild(a); ln.appendChild(b); ln.appendChild(c);
  logEl.insertBefore(ln, logEl.firstChild);
  while (logEl.childNodes.length > 14) logEl.removeChild(logEl.lastChild);
}
function push(cls){
  for (var i = 0; i < N - 1; i++) bars[i].className = bars[i + 1].className;
  bars[N - 1].className = 'hb-b ' + cls;
}
for (var k = 0; k < N; k++) bars[k].className = 'hb-b' + (k < 6 ? ' hb-void' : '');
log('HB', 'Logon accepted · ResetSeqNumFlag=N · hb 30s');
function tick(){
  if (!root.isConnected) return;
  var stall = Math.random() < 0.07 && mode === 'sync';
  if (stall){
    miss++;
    push('hb-miss');
    lastEl.textContent = (miss * TICK / 1000).toFixed(1) + 's';
    if (miss === 2){
      testReq++; trEl.textContent = testReq;
      log('TEST', 'TestRequest 1084=TR' + (7100 + testReq) + ' · no HB for ' + (miss * TICK / 1000).toFixed(1) + 's');
      mode = 'stall';
      stEl.textContent = '○ NO HEARTBEAT'; stEl.className = 'hb-state hb-stall';
    }
    return;
  }
  if (mode === 'stall'){
    var lost = 2 + ((Math.random() * 6) | 0);
    var from = seqIn, to = seqIn + lost + 1;
    gaps++; resend++;
    gpEl.textContent = gaps; rrEl.textContent = resend;
    log('GAP', 'MsgSeqNum ' + grp(from) + ' → ' + grp(to) + ' · missing ' + lost);
    log('RSND', 'ResendRequest ' + grp(from + 1) + '-' + grp(to - 1) + ' sent');
    seqIn = to;
    mode = 'recov'; recov = 3;
    stEl.textContent = '◐ RECOVERING'; stEl.className = 'hb-state hb-recov';
    miss = 0;
    push('hb-now');
    return;
  }
  if (mode === 'recov'){
    recov--;
    if (recov <= 0){
      log('FILL', 'gap fill complete · lat ' + (180 + ((Math.random() * 260) | 0)) + 'ms · seq aligned');
      mode = 'sync';
      stEl.textContent = '● IN SYNC'; stEl.className = 'hb-state hb-sync';
    }
  }
  miss = 0;
  seqIn += 30 + ((Math.random() * 230) | 0);
  seqOut += (Math.random() * 4) | 0;
  inEl.textContent = grp(seqIn);
  outEl.textContent = grp(seqOut);
  lastEl.textContent = (TICK / 1000).toFixed(1) + 's';
  push('hb-now');
  var r = Math.random();
  if (r < 0.10) log('HB', 'Heartbeat 35=0 · rtt ' + (0.6 + Math.random() * 1.4).toFixed(1) + 'ms');
  else if (r < 0.17) log('APP', 'ExecutionReport 150=F · ' + (1 + ((Math.random() * 40) | 0)) + ' fills · in ' + grp(seqIn));
  else if (r < 0.21) log('APP', 'NewOrderSingle burst · ' + (2 + ((Math.random() * 9) | 0)) + ' out · clOrdID BLTX-' + (60000 + ((Math.random() * 9000) | 0)));
}
tick();
var iv = setInterval(tick, TICK);

