var GW = [
  {n:'GW-A',  cap:7600, base:5940, out:5940, rej:3},
  {n:'GW-B',  cap:7600, base:5210, out:5210, rej:1},
  {n:'GW-C',  cap:5200, base:3480, out:3480, rej:0},
  {n:'DMA-1', cap:3400, base:2410, out:2410, rej:7},
  {n:'ALGO-2',cap:2200, base:1372, out:1372, rej:2}
];
var CAP = GW.reduce(function(a, g){ return a + g.cap; }, 0);
var W = 8;
var rowsEl = root.querySelector('.gw-rows');
var bigEl = root.querySelector('.gw-big'), capEl = root.querySelector('.gw-cap');
var utilEl = root.querySelector('.gw-util'), fillEl = root.querySelector('.gw-fill');
var tokEl = root.querySelector('.gw-tok'), ackEl = root.querySelector('.gw-ack');
capEl.textContent = 'of ' + grp(CAP) + ' cap';
var els = GW.map(function(g){
  var d = document.createElement('div');
  d.className = 'gw-row';
  d.innerHTML = '<span class="gw-nm"></span><span class="gw-out"></span><span class="gw-bar"><span class="gw-on"></span><span class="gw-off"></span></span><span class="gw-pct"></span><span class="gw-q"></span><span class="gw-rej"></span>';
  d.children[0].textContent = g.n;
  rowsEl.appendChild(d);
  return d;
});
function grp(n){ return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function rep(c, n){ return n > 0 ? new Array(n + 1).join(c) : ''; }
function band(u){ return u < 70 ? 'lo' : u < 90 ? 'mid' : 'hi'; }
var tokens = 173;
function draw(){
  if (!root.isConnected) return;
  var total = 0;
  for (var i = 0; i < GW.length; i++){
    var g = GW[i], e = els[i];
    var drift = (g.base - g.out) * 0.22 + g.base * (Math.random() - 0.5) * 0.11;
    g.out = Math.max(120, Math.min(g.cap * 0.99, g.out + drift));
    if (Math.random() < 0.02) g.rej += 1;
    var u = g.out / g.cap * 100;
    var q = Math.round(9 + 260 * Math.pow(u / 100, 3.2));
    var on = Math.max(0, Math.min(W, Math.round(u / 100 * W)));
    total += g.out;
    e.children[1].textContent = grp(g.out);
    e.children[2].children[0].textContent = rep('█', on);
    e.children[2].children[0].className = 'gw-on gw-' + band(u);
    e.children[2].children[1].textContent = rep('█', W - on);
    e.children[3].textContent = Math.round(u);
    e.children[3].className = 'gw-pct gw-' + band(u);
    e.children[4].textContent = q;
    e.children[5].textContent = g.rej;
    e.children[5].className = 'gw-rej' + (g.rej > 5 ? ' gw-flag' : '');
  }
  var au = total / CAP * 100;
  bigEl.textContent = grp(total);
  utilEl.textContent = au.toFixed(1) + '%';
  utilEl.className = 'gw-util gw-' + band(au);
  fillEl.style.width = au.toFixed(1) + '%';
  fillEl.className = 'gw-fill' + (au < 70 ? '' : au < 90 ? ' gw-warn' : ' gw-hot');
  tokens = Math.max(0, Math.min(200, tokens + 40 - Math.round(Math.random() * 70)));
  var tb = Math.round(tokens / 200 * 5);
  tokEl.innerHTML = 'tokens ' + rep('▓', tb) + rep('░', 5 - tb) + ' <b>' + tokens + '</b>';
  ackEl.textContent = 'ack p99 ' + Math.round(96 + au * 1.4) + 'µs';
}
draw();
var iv = setInterval(draw, 1100);

