js:
var V = [
  {m:'XNYS', off:-4, ses:[[570,960]],           pre:[240,570]},
  {m:'GLBX', off:-5, ses:[[0,960],[1020,1440]], pre:null, wk:1},
  {m:'XLON', off:1,  ses:[[480,990]],           pre:[420,480]},
  {m:'XETR', off:2,  ses:[[540,1050]],          pre:[510,540]},
  {m:'XTKS', off:9,  ses:[[540,690],[750,930]], pre:[480,540]},
  {m:'XHKG', off:8,  ses:[[570,720],[780,960]], pre:[540,570]},
  {m:'XSES', off:8,  ses:[[540,720],[780,1020]],pre:[510,540]},
  {m:'XASX', off:10, ses:[[600,960]],           pre:[420,600]}
];
var rowsEl = root.querySelector('.cw-rows'), utcEl = root.querySelector('.cw-utc'), tallyEl = root.querySelector('.cw-tally');
var els = V.map(function(v){
  var d = document.createElement('div');
  d.className = 'cw-row';
  d.innerHTML = '<span class="cw-mic"></span><span class="cw-time"></span><span class="cw-st"></span><span class="cw-bar"><span class="cw-on"></span><span class="cw-off"></span></span><span class="cw-cd"></span>';
  d.children[0].textContent = v.m;
  rowsEl.appendChild(d);
  return d;
});
function pad(n){ return (n < 10 ? '0' : '') + n; }
function rep(c, n){ return n > 0 ? new Array(n + 1).join(c) : ''; }
function state(v, day, min){
  if (v.wk){
    if (day === 6) return 'CLOSED';
    if (day === 0) return min >= 1020 ? 'OPEN' : 'CLOSED';
    if (day === 5) return min < 960 ? 'OPEN' : 'CLOSED';
    return (min < 960 || min >= 1020) ? 'OPEN' : 'BREAK';
  }
  if (day === 0 || day === 6) return 'CLOSED';
  for (var i = 0; i < v.ses.length; i++) if (min >= v.ses[i][0] && min < v.ses[i][1]) return 'OPEN';
  if (v.ses.length > 1 && min >= v.ses[0][1] && min < v.ses[1][0]) return 'LUNCH';
  if (v.pre && min >= v.pre[0] && min < v.pre[1]) return 'PRE';
  return 'CLOSED';
}
function nextChange(v, day, min){
  var s = state(v, day, min), d = day, m = min;
  for (var k = 1; k <= 4400; k++){
    m++; if (m >= 1440){ m = 0; d = (d + 1) % 7; }
    if (state(v, d, m) !== s) return k;
  }
  return 4400;
}
function progress(v, day, min){
  if (v.wk) return -1;
  for (var i = 0; i < v.ses.length; i++){
    if (min >= v.ses[i][0] && min < v.ses[i][1])
      return (min - v.ses[i][0]) / (v.ses[i][1] - v.ses[i][0]);
  }
  return -1;
}
function cdText(sec){
  if (sec >= 86400) return (sec / 86400 | 0) + 'd ' + pad((sec % 86400 / 3600) | 0) + 'h';
  return pad((sec / 3600) | 0) + ':' + pad(((sec % 3600) / 60) | 0) + ':' + pad(sec % 60);
}
var LAB = {OPEN:'● OPEN', PRE:'◐ PRE', LUNCH:'◑ LUNCH', BREAK:'◑ BREAK', CLOSED:'○ CLOSED'};
var CLS = {OPEN:'cw-open', PRE:'cw-pre', LUNCH:'cw-lunch', BREAK:'cw-lunch', CLOSED:'cw-closed'};
var VERB = {OPEN:'cls', PRE:'opn', LUNCH:'res', BREAK:'res', CLOSED:'opn'};
function tick(){
  if (!root.isConnected) return;
  var now = Date.now(), u = new Date(now);
  utcEl.innerHTML = 'UTC ' + pad(u.getUTCHours()) + '<span class="cw-sec">:</span>' + pad(u.getUTCMinutes()) + ':' + pad(u.getUTCSeconds());
  var tally = {OPEN:0, PRE:0, LUNCH:0, BREAK:0, CLOSED:0};
  for (var i = 0; i < V.length; i++){
    var v = V[i], e = els[i];
    var t = new Date(now + v.off * 3600000);
    var day = t.getUTCDay(), h = t.getUTCHours(), mi = t.getUTCMinutes(), se = t.getUTCSeconds();
    var min = h * 60 + mi;
    var st = state(v, day, min);
    tally[st]++;
    var secsLeft = nextChange(v, day, min) * 60 - se;
    e.children[1].textContent = pad(h) + ':' + pad(mi) + ':' + pad(se);
    e.children[2].textContent = LAB[st];
    var p = st === 'OPEN' ? progress(v, day, min) : -1;
    var on = p < 0 ? 0 : Math.max(0, Math.min(6, Math.round(p * 6)));
    e.children[3].children[0].textContent = p < 0 ? '' : rep('█', on);
    e.children[3].children[1].textContent = p < 0 ? (v.wk && st === 'OPEN' ? '  24h ' : '') : rep('█', 6 - on);
    e.children[4].textContent = VERB[st] + ' ' + cdText(secsLeft);
    e.className = 'cw-row ' + CLS[st];
  }
  tallyEl.textContent = tally.OPEN + ' open · ' + tally.PRE + ' pre · ' + (tally.LUNCH + tally.BREAK) + ' break · ' + tally.CLOSED + ' closed';
}
tick();
var iv = setInterval(tick, 1000);

