js:
var L = [
  {k:'ORD NOTNL', v:1.42e6, lim:5e6,   f:'usd',  vol:0.22},
  {k:'NET DELTA', v:16.2e6, lim:25e6,  f:'usd',  vol:0.06},
  {k:'DAY P&L',   v:-412000,lim:-1.5e6,f:'usd',  vol:0.09},
  {k:'MSG RATE',  v:812,    lim:1000,  f:'rate', vol:0.13},
  {k:'ORD:FILL',  v:4.2,    lim:8,     f:'x',    vol:0.16},
  {k:'POS NVDA',  v:38000,  lim:50000, f:'sh',   vol:0.06}
];
for (var q = 0; q < L.length; q++) L[q].base = L[q].v;
var W = 6, HOLD = 1200;
var rowsEl = root.querySelector('.ks-rows'), stateEl = root.querySelector('.ks-state');
var labEl = root.querySelector('.ks-lab'), metaEl = root.querySelector('.ks-meta');
var btn = root.querySelector('.ks-kill'), fill = root.querySelector('.ks-fill'), txt = root.querySelector('.ks-txt');
var hint = root.querySelector('.ks-hint');
var els = L.map(function(r){
  var d = document.createElement('div');
  d.className = 'ks-row';
  d.innerHTML = '<span class="ks-k"></span><span class="ks-v"></span><span class="ks-bar"><span class="ks-on"></span><span class="ks-off"></span></span><span class="ks-p"></span><span class="ks-s"></span>';
  d.children[0].textContent = r.k;
  rowsEl.appendChild(d);
  return d;
});
function rep(c, n){ return n > 0 ? new Array(n + 1).join(c) : ''; }
function money(v){
  var a = Math.abs(v), s = v < 0 ? '-' : '';
  if (a >= 1e6) return s + '$' + (a / 1e6).toFixed(2) + 'M';
  if (a >= 1e3) return s + '$' + Math.round(a / 1e3) + 'k';
  return s + '$' + Math.round(a);
}
function fmt(r){
  if (r.f === 'usd') return money(r.v);
  if (r.f === 'rate') return Math.round(r.v) + '/s';
  if (r.f === 'x') return r.v.toFixed(1) + ':1';
  return (r.v / 1000).toFixed(1) + 'k';
}
var mode = 'live';
function paint(){
  var breach = 0, warn = 0;
  for (var i = 0; i < L.length; i++){
    var r = L[i], e = els[i];
    var u = Math.abs(r.v) / Math.abs(r.lim) * 100;
    var band = u < 70 ? 'ok' : u < 90 ? 'warn' : 'brch';
    if (band === 'brch') breach++; else if (band === 'warn') warn++;
    var on = Math.max(0, Math.min(W, Math.round(u / 100 * W)));
    e.children[1].textContent = fmt(r);
    e.children[1].className = 'ks-v' + (r.v < 0 ? ' ks-brch' : '');
    e.children[2].children[0].textContent = rep('█', on);
    e.children[2].children[0].className = 'ks-on ks-' + band;
    e.children[2].children[1].textContent = rep('█', W - on);
    e.children[3].textContent = Math.round(u) + '%';
    e.children[4].textContent = band === 'ok' ? '· OK' : band === 'warn' ? '! WARN' : 'x BRCH';
    e.children[4].className = 'ks-s ks-' + band;
  }
  if (mode === 'halt') return;
  if (breach){
    mode = 'block';
    stateEl.className = 'ks-state ks-block';
    labEl.textContent = '◐ NEW ORDERS BLOCKED';
    metaEl.textContent = breach + ' limit breach · cancels allowed';
  } else {
    mode = 'live';
    stateEl.className = 'ks-state ks-live';
    labEl.textContent = '● TRADING ENABLED';
    metaEl.textContent = '6 venues · 214 working · ' + warn + ' near limit';
  }
}
function pad(n){ return (n < 10 ? '0' : '') + n; }
function halt(){
  mode = 'halt';
  var d = new Date();
  stateEl.className = 'ks-state ks-halt';
  labEl.textContent = '■ HALTED ' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
  metaEl.textContent = '214 cancelled · 6 venues · 318ms';
  btn.className = 'ks-kill ks-done';
  txt.textContent = 'RESET DESK';
  fill.style.width = '0%';
  hint.textContent = 'kill sent to all gateways';
}
function reset(){
  mode = 'live';
  btn.className = 'ks-kill';
  txt.textContent = 'HOLD TO KILL';
  hint.textContent = 'hold 1.2s · Space or Enter';
  paint();
}
var t0 = 0, raf = 0;
function step(){
  if (!root.isConnected) return;
  var p = Math.min(1, (Date.now() - t0) / HOLD);
  fill.style.width = (p * 100).toFixed(1) + '%';
  txt.textContent = p < 1 ? 'KILLING ' + Math.round(p * 100) + '%' : 'HOLD TO KILL';
  if (p >= 1){ raf = 0; halt(); return; }
  raf = requestAnimationFrame(step);
}
function start(){
  if (mode === 'halt' || raf) return;
  btn.classList.add('ks-armed');
  t0 = Date.now();
  raf = requestAnimationFrame(step);
}
function stop(){
  if (!raf) return;
  cancelAnimationFrame(raf); raf = 0;
  btn.classList.remove('ks-armed');
  fill.style.width = '0%';
  txt.textContent = 'HOLD TO KILL';
}
btn.addEventListener('pointerdown', function(e){ if (mode !== 'halt'){ e.preventDefault(); start(); } });
btn.addEventListener('pointerup', stop);
btn.addEventListener('pointerleave', stop);
btn.addEventListener('pointercancel', stop);
btn.addEventListener('keydown', function(e){
  if (e.key !== ' ' && e.key !== 'Enter') return;
  e.preventDefault();
  if (mode === 'halt'){ reset(); return; }
  if (!e.repeat) start();
});
btn.addEventListener('keyup', function(e){ if (e.key === ' ' || e.key === 'Enter') stop(); });
btn.addEventListener('click', function(){ if (mode === 'halt') reset(); });
paint();
var iv = setInterval(function(){
  if (!root.isConnected) return;
  if (mode === 'halt') return;
  for (var i = 0; i < L.length; i++){
    var r = L[i];
    r.v += (r.base - r.v) * 0.3 + Math.abs(r.base) * (Math.random() - 0.5) * r.vol * (r.base < 0 ? -1 : 1);
  }
  paint();
}, 1300);

