js:
var B = [
  {t:'QTY MISMATCH', n:11, v:1620000, age:'T-3', own:'',
   d1:'AAPL US · 037833100 · OMS 12,000 vs PB 11,500',
   d2:'Δ 500 sh @ 224.16 = $112,080 · largest of 11'},
  {t:'PRICE DIFF', n:7, v:18400, age:'T-2', own:'',
   d1:'MSFT US · 594918104 · 2,200 sh · 418.22 vs 418.05',
   d2:'line $920,084 · Δ 0.17 = $374 impact · corp action suspect'},
  {t:'MISSING @ PB', n:6, v:710000, age:'T-1', own:'',
   d1:'NVDA US · 67066G104 · 3,200 @ 118.44 = $379,008',
   d2:'booked OMS 14:41 · no PB record · allocation not sent'},
  {t:'MISSING @ OMS', n:4, v:580000, age:'T-1', own:'',
   d1:'IBM US · 459200101 · 1,900 @ 238.50 = $453,150',
   d2:'PB only · give-up from XCHI · no parent order'},
  {t:'SETTLE DATE', n:3, v:412800, age:'T-2', own:'',
   d1:'JPM US · 46625H100 · 1,250 @ 248.40 = $310,500',
   d2:'OMS T+1 2026-08-31 vs PB T+2 2026-09-01 · fail risk'},
  {t:'FX RATE', n:2, v:4200, age:'T-1', own:'',
   d1:'EURUSD · EUR 5,000,000 · OMS 1.0842 vs PB 1.0839',
   d2:'Δ 3 pip = $1,500 · 4pm WMR vs intraday snap'}
];
var AGE = [['T-1', 18], ['T-2', 9], ['T-3+', 6]];
var TOTAL = 12514;
var rowsEl = root.querySelector('.rb-rows'), d1 = root.querySelector('.rb-d1'), d2 = root.querySelector('.rb-d2');
var openEl = root.querySelector('.rb-open');
function grp(n){ return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function usd(v){
  return v >= 1e6 ? '$' + (v / 1e6).toFixed(2) + 'M' : v >= 1e3 ? '$' + (v / 1e3).toFixed(1) + 'k' : '$' + v;
}
var breaks = 0, atRisk = 0;
for (var i = 0; i < B.length; i++){ breaks += B[i].n; atRisk += B[i].v; }
var matched = TOTAL - breaks;
root.querySelector('.rb-m').textContent = grp(matched) + '/' + grp(TOTAL);
root.querySelector('.rb-rate').textContent = (matched / TOTAL * 100).toFixed(2) + '%';
root.querySelector('.rb-n').textContent = breaks;
root.querySelector('.rb-val').textContent = usd(atRisk);
var agSum = AGE[0][1] + AGE[1][1] + AGE[2][1];
root.querySelector('.rb-s1').style.flex = AGE[0][1] / agSum;
root.querySelector('.rb-s2').style.flex = AGE[1][1] / agSum;
root.querySelector('.rb-s3').style.flex = AGE[2][1] / agSum;
root.querySelector('.rb-l1').textContent = '■ T-1 ' + AGE[0][1];
root.querySelector('.rb-l2').textContent = '■ T-2 ' + AGE[1][1];
root.querySelector('.rb-l3').textContent = '■ T-3+ ' + AGE[2][1];
var els = B.map(function(b, ix){
  var d = document.createElement('div');
  d.className = 'rb-row';
  d.innerHTML = '<span class="rb-ty"></span><span class="rb-c"></span><span class="rb-v"></span><span class="rb-ag"></span><span class="rb-ow"></span>';
  d.children[0].textContent = b.t;
  d.children[1].textContent = b.n;
  d.children[2].textContent = usd(b.v);
  d.children[3].textContent = b.age;
  d.children[3].className = 'rb-ag' + (b.age === 'T-3' ? ' rb-old' : '');
  d.addEventListener('click', function(){ pick(ix); root.focus(); });
  rowsEl.appendChild(d);
  return d;
});
var sel = 0;
function paint(){
  var open = 0;
  for (var i = 0; i < B.length; i++){
    els[i].className = 'rb-row' + (i === sel ? ' rb-sel' : '');
    els[i].children[4].textContent = B[i].own || 'OPEN';
    els[i].children[4].className = 'rb-ow' + (B[i].own ? ' rb-asgn' : '');
    if (!B[i].own) open++;
  }
  openEl.textContent = open;
  d1.textContent = B[sel].d1;
  d2.textContent = B[sel].d2;
}
function pick(i){ sel = (i + B.length) % B.length; paint(); }
function assign(){
  var b = B[sel];
  b.own = b.own ? '' : 'MW';
  paint();
  d2.textContent = b.own
    ? 'assigned to MW · ' + b.n + ' items · SLA T+1 17:00 · ticket REC-' + (4180 + sel)
    : b.d2;
  var el = els[sel];
  el.classList.remove('rb-flash');
  void el.offsetWidth;
  el.classList.add('rb-flash');
}
root.addEventListener('keydown', function(e){
  if (e.key === 'ArrowDown'){ pick(sel + 1); e.preventDefault(); }
  else if (e.key === 'ArrowUp'){ pick(sel - 1); e.preventDefault(); }
  else if (e.key === 'Enter'){ assign(); e.preventDefault(); }
});
paint();
